"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[945],{8820(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>c});var i=n(4848),o=n(8453);const a={title:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",date:new Date("2026-05-28T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"t-hardware",article_tags:{zh:["\u8a18\u61b6\u9ad4","\u904a\u6232\u6a5f","NVIDIA","AI \u6d6a\u6f6e","\u4f9b\u61c9\u93c8"],en:["memory","console-gaming","nvidia","ai-wave","supply-chain"]},keywords:["900-layer V-NAND","Switch 2","Steam Deck","HBM","memory shortage"],summary:"Deconstructing the technology behind Samsung's 900-layer V-NAND, and explaining how AI's insatiable memory demand ripples into consumer electronics, forcing gamers to pay for the AI revolution.",status:"published",reading_time:10,sidebar_label:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",sidebar_position:20260528,description:"Deconstructing the technology behind Samsung's 900-layer V-NAND, and explaining how AI's insatiable memory demand ripples into consumer electronics, forcing gamers to pay for the AI revolution."},s="The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",r={id:"TechNotes/900 \u5c64\u7684\u771f\u76f8\uff1a\u7576\u4f60\u7684 Switch \u548c Steam Deck \u5728\u66ff AI \u8cb7\u55ae",title:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",description:"Deconstructing the technology behind Samsung's 900-layer V-NAND, and explaining how AI's insatiable memory demand ripples into consumer electronics, forcing gamers to pay for the AI revolution.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/900 \u5c64\u7684\u771f\u76f8\uff1a\u7576\u4f60\u7684 Switch \u548c Steam Deck \u5728\u66ff AI \u8cb7\u55ae.md",sourceDirName:"TechNotes",slug:"/TechNotes/900 \u5c64\u7684\u771f\u76f8\uff1a\u7576\u4f60\u7684 Switch \u548c Steam Deck \u5728\u66ff AI \u8cb7\u55ae",permalink:"/en/docs/TechNotes/900 \u5c64\u7684\u771f\u76f8\uff1a\u7576\u4f60\u7684 Switch \u548c Steam Deck \u5728\u66ff AI \u8cb7\u55ae",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:20260528,frontMatter:{title:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",date:"2026-05-28T00:00:00.000Z",lang:"en",section:"sober-record",topic:"t-hardware",article_tags:{zh:["\u8a18\u61b6\u9ad4","\u904a\u6232\u6a5f","NVIDIA","AI \u6d6a\u6f6e","\u4f9b\u61c9\u93c8"],en:["memory","console-gaming","nvidia","ai-wave","supply-chain"]},keywords:["900-layer V-NAND","Switch 2","Steam Deck","HBM","memory shortage"],summary:"Deconstructing the technology behind Samsung's 900-layer V-NAND, and explaining how AI's insatiable memory demand ripples into consumer electronics, forcing gamers to pay for the AI revolution.",status:"published",reading_time:10,sidebar_label:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI",sidebar_position:20260528,description:"Deconstructing the technology behind Samsung's 900-layer V-NAND, and explaining how AI's insatiable memory demand ripples into consumer electronics, forcing gamers to pay for the AI revolution."},sidebar:"docs",previous:{title:"HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic",permalink:"/en/docs/TechNotes/HBM \u4e0d\u662f\u4e0b\u4e00\u500b\u53f0\u7a4d\u96fb\uff1a\u8a18\u61b6\u9ad4\u8207\u908f\u8f2f\u6676\u7247\u7684\u7d50\u69cb\u6027\u9d3b\u6e9d"},next:{title:"I Asked AI 'Should I Still Buy Memory Stocks?' \u2014 And Discovered a Much Bigger Problem",permalink:"/en/docs/TechNotes/\u6211\u554f\u4e86 AI\u300c\u8a18\u61b6\u9ad4\u80a1\u9084\u80fd\u4e0d\u80fd\u8cb7\u300d"}},h={},c=[{value:"Two Headlines, One Week",id:"two-headlines-one-week",level:2},{value:"900 Layers Is Not 900 Layers",id:"900-layers-is-not-900-layers",level:2},{value:"What Matters Is Not the Layer Count, but the Direction",id:"what-matters-is-not-the-layer-count-but-the-direction",level:2},{value:"But None of This Is What Ordinary People Should Care About",id:"but-none-of-this-is-what-ordinary-people-should-care-about",level:2},{value:"The Cracks Have Already Appeared",id:"the-cracks-have-already-appeared",level:2},{value:"The Most Ironic Hedge",id:"the-most-ironic-hedge",level:2},{value:"Conclusion: Technology Is Advancing, but Your Wallet Is Retreating",id:"conclusion-technology-is-advancing-but-your-wallet-is-retreating",level:2}];function l(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"the-truth-behind-900-layers-when-your-switch-and-steam-deck-are-footing-the-bill-for-ai",children:"The Truth Behind 900 Layers: When Your Switch and Steam Deck Are Footing the Bill for AI"})}),"\n",(0,i.jsx)(t.h2,{id:"two-headlines-one-week",children:"Two Headlines, One Week"}),"\n",(0,i.jsx)(t.p,{children:"In the last week of May 2026, two news stories appeared on tech media almost simultaneously."}),"\n",(0,i.jsx)(t.p,{children:'The first: Samsung announced the successful development of the world\'s first 900-layer V-NAND prototype chip. Media headlines erupted in celebration \u2014 "Major Breakthrough in Memory Technology," "Reshaping the Flash Memory Competitive Landscape," "The Storage Revolution of the AI Era."'}),"\n",(0,i.jsx)(t.p,{children:'The second: Valve announced a steep price hike for the Steam Deck OLED, with the 1TB version jumping from $650 to $950 \u2014 a 46% increase. The reason was a single sentence: "rising memory and storage costs."'}),"\n",(0,i.jsx)(t.p,{children:'In the same week, one side was celebrating a memory technology "breakthrough," while on the other side consumers were paying for memory shortages. This is no coincidence \u2014 it is two faces of the same structural problem.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"900-layers-is-not-900-layers",children:"900 Layers Is Not 900 Layers"}),"\n",(0,i.jsx)(t.p,{children:'Let\'s start with that "breakthrough."'}),"\n",(0,i.jsx)(t.p,{children:"Samsung's 900-layer V-NAND was not etched from top to bottom as a 900-layer structure on a single wafer. It uses a technology called CMB (Cell Multi-Bonding) to bond two 450-layer wafers together, forming a 900-layer package."}),"\n",(0,i.jsx)(t.p,{children:"This distinction matters."}),"\n",(0,i.jsx)(t.p,{children:"Think of building a skyscraper. Traditional 3D NAND builds layer upon layer on a single foundation. Going from 64 layers to 128 is manageable; reaching 232 starts to get painful; above 300 layers, you approach physical limits \u2014 the aspect ratio of etched holes becomes absurd (equivalent to drilling a straw from the top of Taipei 101 down to the underground car park), yields plummet, stress and warpage spike, and costs rise not linearly but exponentially."}),"\n",(0,i.jsx)(t.p,{children:"Samsung's approach: instead of building one 900-storey skyscraper, build two 450-storey towers and connect them with a skybridge."}),"\n",(0,i.jsx)(t.p,{children:'This is genuinely difficult engineering \u2014 bonding precision, warpage correction, and electrical connectivity are all real technical challenges. But it is an entirely different order of achievement from "etching 900 layers on a single wafer." More critically: this is a laboratory prototype, not a production product. Samsung\'s actual highest layer count in mass production is 286 layers (V9); the next generation V10 (approximately 430 layers) is not expected to enter mass production until the second half of 2026. Between prototype and mass production lie several mountains: yield, cost, endurance, and stability.'}),"\n",(0,i.jsx)(t.p,{children:'But media headlines won\'t tell you any of this. The three characters "900 layers" are enough to make a stock price jump, enough for a KOL to publish a "NAND Technology Breakthrough" explainer. As for the difference between 450+450 and a true 900 layers \u2014 that\'s left for those who can tell the difference.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"what-matters-is-not-the-layer-count-but-the-direction",children:"What Matters Is Not the Layer Count, but the Direction"}),"\n",(0,i.jsx)(t.p,{children:"The truly significant aspect of Samsung's CMB technology is not the number \"900\" but the industry direction it reveals: NAND is following HBM's well-worn path."}),"\n",(0,i.jsx)(t.p,{children:"What was the essential revolution of HBM? Not making individual DRAM chips larger, but stacking many of them using TSV (through-silicon via) technology. Now NAND is heading down the same road \u2014 no longer pushing for the maximum layer count on a single wafer, but using advanced bonding techniques to combine multiple wafers into a single system."}),"\n",(0,i.jsx)(t.p,{children:'This signals a common pivot across the entire memory industry: from "process shrinking" to "packaging integration." CoWoS, SoIC, and Foveros on the CPU/GPU side; TSV stacking on the HBM side; CMB on the NAND side \u2014 the underlying logic is the same. Physical limits have been reached; rather than continuing to shrink, the strategy is to turn multiple dies into one system.'}),"\n",(0,i.jsx)(t.p,{children:'This also means that the competitive core for NAND manufacturers will shift from "who stacks higher" to "who bonds better" \u2014 bonding precision, bonding density, bonding yield, bonding cost. And predictably, once bonding technology matures, product differentiation between manufacturers will narrow further. An SSD assembled via CMB and a competitor\'s SSD assembled via Hybrid Bonding will ultimately ship to the same specification. Different technical paths, same destination \u2014 still a commodity.'}),"\n",(0,i.jsx)(t.p,{children:'Here\'s a prediction for something about to happen: the "Layer Count Definition War." If 450+450 can be called 900 layers, can 256+256+256 be called 768 layers? Marketing departments will inevitably start playing number games. Comparing "layer counts" across manufacturers will become like comparing "megapixels" on smartphones \u2014 the numbers keep getting bigger, but their actual meaning becomes increasingly blurred. For the stock market, however, blurriness is the best fuel \u2014 every "new record" feeds another round of explainers, another wave of buy signals, another batch of retail investors entering the market. The technical breakthrough is real, but the speed at which it gets translated into investment narrative is always ten times faster than the speed at which it becomes a mass-produced product.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"but-none-of-this-is-what-ordinary-people-should-care-about",children:"But None of This Is What Ordinary People Should Care About"}),"\n",(0,i.jsx)(t.p,{children:"The above is technical analysis. For most people, the real question that hits home is not how many layers Samsung's NAND has stacked, but: why has my gaming console suddenly become so much more expensive?"}),"\n",(0,i.jsx)(t.p,{children:"The answer is simple: you are footing the bill for AI's memory appetite."}),"\n",(0,i.jsx)(t.p,{children:'In May 2026, Nintendo announced a $50 price increase for the Switch 2 in the United States (from $449.99 to $499.99), effective September 1. Japan moved even earlier, adding \xa510,000 from May 25. Even Nintendo Switch Online subscriptions went up. Nintendo\'s official wording was "changing market conditions," but the financial report was explicit: rising memory costs imposed approximately \xa5100 billion in additional operating costs for the fiscal year. Nintendo itself expects post-hike unit sales to drop from nearly 20 million the previous year to 16.5 million. Raise prices to save margins, sacrifice volume \u2014 this is the reality of memory cost pass-through.'}),"\n",(0,i.jsx)(t.p,{children:"The same week, Valve raised the Steam Deck OLED 1TB from $650 to $950, and the 512GB from $550 to $790. A 1TB Steam Deck now costs more than a PS5 Pro. Valve explicitly cited rising memory and storage costs, and even delayed the pricing and launch of the Steam Machine and Steam Frame VR headset for the same reason."}),"\n",(0,i.jsx)(t.p,{children:"Sony has already raised PS5 prices, with increases up to $150. Microsoft raised Xbox prices. Sony is even considering delaying the PlayStation 6 to 2028 or even 2029. Nintendo's stock price has fallen more than 30% year-to-date in 2026 under memory cost pressure."}),"\n",(0,i.jsx)(t.p,{children:'The entire gaming industry is being reshaped by memory shortages. The root cause is Samsung, SK Hynix, and Micron redirecting massive production capacity from consumer-grade DRAM and NAND to the more profitable AI-oriented HBM. IDC analysts used a weighty term: "Structural Reset" \u2014 this is not a traditional cyclical fluctuation but a fundamental shift in how memory production is allocated. AI infrastructure\'s priority, in the supply chain food chain, ranks above your gaming console, your smartphone, and your laptop.'}),"\n",(0,i.jsx)(t.p,{children:"There is a deeper layer of irony here that most people do not see."}),"\n",(0,i.jsxs)(t.p,{children:["The memory-devouring GPUs in AI data centres \u2014 NVIDIA's H100, B200 \u2014 exist because over the past two decades, generation after generation of PC gamers bought graphics cards, subsidising NVIDIA's R&D costs for parallel computing (CUDA). Those GPUs' large-area dies can be mass-produced because TSMC honed its extreme yield rates for large dies using gaming GPU orders. In other words: ",(0,i.jsx)(t.strong,{children:"gamers are the unwitting financiers of the AI revolution \u2014 the money they spent buying GeForce cards nurtured the very industry that is now stealing their memory supply."})]}),"\n",(0,i.jsx)(t.p,{children:"And now NVIDIA's approach is even more direct. Facing the enormous profits from AI orders, NVIDIA plans to cut consumer RTX 50 series GPU supply by 30% to 40% in the first half of 2026, with some models discontinued outright \u2014 because the same memory chips generate several times more revenue when installed in AI servers than in gaming graphics cards. NVIDIA can make this trade-off without hesitation, not because it doesn't care about the gaming market, but because its CUDA ecosystem has locked the entire global AI industry in \u2014 AI customers have no choice but to buy from NVIDIA, so NVIDIA can always prioritise the most profitable end of the market."}),"\n",(0,i.jsxs)(t.p,{children:["The causal chain is long: gamers' money nurtured NVIDIA \u2192 NVIDIA's CUDA locked in the AI industry \u2192 AI's memory hunger cannibalised gaming's component supply \u2192 gaming consoles got more expensive, and gamers foot the bill again. The invoice went full circle and landed back on the same group of people. In my book ",(0,i.jsx)(t.a,{href:"https://mythogenengine.com/en/",children:(0,i.jsx)(t.em,{children:"Game Victory: From Pixels to AI, How Entertainment Secretly Reshaped Global Tech Supremacy"})}),", I spent eleven chapters tracing this forty-year causal chain from gaming to AI \u2014 memory price hikes are merely the latest deferred invoice on this chain."]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"the-cracks-have-already-appeared",children:"The Cracks Have Already Appeared"}),"\n",(0,i.jsx)(t.p,{children:'But the story doesn\'t end here. Even as the "demand exceeds supply" narrative remains at full volume, cracks have quietly appeared.'}),"\n",(0,i.jsx)(t.p,{children:"In late March 2026, Google released an AI memory compression technology called TurboQuant, capable of reducing AI inference memory usage to one-sixth. The moment the news broke, Samsung fell 4.71%, SK Hynix fell 6.23%, Micron fell 6.97%, and Sandisk plunged 11.02%. Cloudflare's CEO called it Google's \"DeepSeek moment.\""}),"\n",(0,i.jsx)(t.p,{children:'The market\'s reaction was brief \u2014 analysts quickly emerged to say "no impact on the big picture," "AI demand remains strong," "the pullback is a buying opportunity." But TurboQuant proved one thing: software-level optimisation can significantly compress the memory requirements of individual workloads. The foundational assumption propping up the narrative that HBM demand will explode forever \u2014 "AI models\' memory efficiency cannot improve significantly" \u2014 is being challenged by technological progress.'}),"\n",(0,i.jsx)(t.p,{children:"The consumer spot market is also loosening. DDR5 spot prices have cumulatively fallen 30% to 40% over the past month. Buyers are starting to wait and see, expecting further downside. DDR5 retail prices have pulled back, though the industry emphasises that contract prices remain stable. Spot and contract markets are telling two different stories \u2014 and history tells us that spot prices are usually leading indicators."}),"\n",(0,i.jsx)(t.p,{children:"Memory prices are expected to peak in Q3 to Q4 of 2026, then begin a slow decline. New capacity \u2014 Samsung's Pyeongtaek P4, SK Hynix's M15X, Micron's new US fab \u2014 will come online progressively between 2027 and 2028. But most of this capacity is built for AI and HBM; relief for consumer-grade supply may take even longer."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"the-most-ironic-hedge",children:"The Most Ironic Hedge"}),"\n",(0,i.jsx)(t.p,{children:'In this entire situation, the most ironic thing is an "investment tip" circulating on social media: think your SSD was overpriced? Buy memory stocks to "hedge."'}),"\n",(0,i.jsx)(t.p,{children:"The logic sounds clever, but it has a fatal blind spot: memory stocks are cyclical stocks."}),"\n",(0,i.jsx)(t.p,{children:"When the cycle reverses and memory prices crash \u2014 and history tells us that day will inevitably come \u2014 your stocks will fall. But the Switch 2 and Steam Deck you already bought at inflated prices won't give you a refund. That $950 Steam Deck you purchased? After memory prices come back down, Valve won't be mailing you a $300 rebate cheque."}),"\n",(0,i.jsx)(t.p,{children:'The so-called "hedge" \u2014 buying at the cycle top \u2014 loses on both sides.'}),"\n",(0,i.jsx)(t.p,{children:"A real hedge is not chasing a cyclical stock at its historic peak. It's understanding what kind of market structure you're facing, and then making the least self-damaging choice within that structure: if you don't urgently need something now, wait; if you do, buy \u2014 but don't deceive yourself into thinking that buying memory stocks will let you \"earn it back.\""}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"conclusion-technology-is-advancing-but-your-wallet-is-retreating",children:"Conclusion: Technology Is Advancing, but Your Wallet Is Retreating"}),"\n",(0,i.jsx)(t.p,{children:'Samsung\'s 900-layer NAND is a real technological achievement, but it is a laboratory prototype \u2014 not a mass-production product that will make your SSD cheaper tomorrow. The NAND industry is pivoting from "stacking higher" to "bonding together" \u2014 an important technical shift, but one that will not change NAND\'s commercial essence as a commodity.'}),"\n",(0,i.jsx)(t.p,{children:"Meanwhile, AI's insatiable appetite for memory is reshaping the entire consumer electronics pricing system. Your gaming console is getting more expensive, your smartphone is getting more expensive, your laptop is getting more expensive \u2014 not because they've gotten better, but because the components used to make them have been commandeered by AI."}),"\n",(0,i.jsx)(t.p,{children:'While KOLs celebrate memory stocks doubling, while investment banks name the next "AI beneficiary sector," while pastel-coloured infographics teach you to buy six stocks that will double \u2014 the person actually footing the bill for this feast is you, walking into a game store after September 1 and discovering that the Switch 2 is another $50 more expensive.'}),"\n",(0,i.jsx)(t.p,{children:'And when this cycle finally reverses \u2014 not "if" but "when" \u2014 those who bought memory stocks at the top will discover: AI companies\' capital expenditure will decelerate, memory prices will crash, stocks will be halved. But your gaming console won\'t get cheaper for it, and your SSD won\'t be refunded. In this structural wealth transfer, retail investors are always the last to enter and the first to be harvested.'}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:'This article is the third in the "Memory Myth" series. The first, [Did Jensen Huang Tell You to Buy These Six Stocks?], deconstructed investment misinformation on social media. The second, [HBM Is Not the Next TSMC: The Structural Chasm Between Memory and Logic], analysed the cyclical nature of the memory industry from the structural level. Together, the three form a complete observation: the technology is real, the demand is real, but the narrative has been packaged \u2014 and the people paying for that packaging are never the ones telling the story.'})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsxs)(t.em,{children:["If you want to know how gamers became the unwitting financiers of the AI revolution, step by step \u2014 from DirectX locking in developers, to CUDA locking in the entire AI industry, to TSMC using gaming GPU orders to hone advanced process yields \u2014 ",(0,i.jsx)(t.a,{href:"https://mythogenengine.com/en/",children:(0,i.jsx)(t.em,{children:"Game Victory: From Pixels to AI, How Entertainment Secretly Reshaped Global Tech Supremacy"})})," traces the complete forty-year causal chain. Memory price hikes are not where the story begins, nor even where it ends. They are simply the invoice on this chain that is closest to you."]})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(4428).A+"",width:"1792",height:"2400"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(1742).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(7635).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(4056).A+"",width:"1696",height:"2528"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(9437).A+"",width:"1696",height:"2528"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(9690).A+"",width:"1696",height:"2528"})})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},4428(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/01-711a0f8ae347098a1c2dd802a8b4ae59.jpg"},1742(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/02 1-488bb7b4064a92497e79cd8ae9c7168e.jpg"},7635(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/03 1-8152e13d1fcf57380862ea3b7c37e3cf.jpg"},4056(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/04 1-023ce43fe4ef707ba8f0857b42ec87c7.jpg"},9437(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/05 1-5215b4e0dae6fe28142aa3d9da07e210.jpg"},9690(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/06 1-1e436f4c46886c82132eac8563a000f4.jpg"},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var i=n(6540);const o={},a=i.createContext(o);function s(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);